-- ============================================================================
--  Tipo de documento de los pacientes atendidos 2026
--  Complemento de insertar_pacientes_atendidos_2026.sql
--
--  Pone tipo_Docu = 'Cédula de Ciudadanía' (valor exacto del catálogo
--  tipo_documento) a los pacientes del archivo que quedaron sin tipo de
--  documento. Solo toca filas con rol paciente y tipo_Docu vacío: no cambia
--  el tipo de documento que ya tuviera cualquier otro registro.
--  Documentos del archivo: 102328
--
--  CÓMO APLICARLO EN CPANEL (después del script de inserción):
--    1. Copia de seguridad de la base.
--    2. phpMyAdmin > base (uoxclxvl_tools) > Importar > este archivo.
-- ============================================================================

SET NAMES utf8mb4;

DROP TABLE IF EXISTS `tmp_docs_pacientes_2026`;
CREATE TABLE `tmp_docs_pacientes_2026` (
  `Numero_D` varchar(20) NOT NULL,
  PRIMARY KEY (`Numero_D`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


UPDATE `users` u
JOIN `tmp_docs_pacientes_2026` t ON t.`Numero_D` = UPPER(TRIM(u.`Numero_D`))
SET u.`tipo_Docu` = 'Cédula de Ciudadanía'
WHERE u.`rol` = 'paciente'
  AND (u.`tipo_Docu` IS NULL OR TRIM(u.`tipo_Docu`) = '');

SELECT ROW_COUNT() AS pacientes_actualizados;

DROP TABLE IF EXISTS `tmp_docs_pacientes_2026`;
